import { MODES } from "../calc/validate.mjs";
import { CVD_TYPES } from "../calc/colour.mjs";
import { CHART_SURFACES } from "../calc/tokens.mjs";
import { LINE, OPACITY, SLOTS } from "../palette.mjs";
import { round } from "./format.mjs";

const f1 = (x) => x.toFixed(1);
const cell = (v, min) => (v < min ? `**${f1(v)}**` : f1(v));

export const buildMarkdown = (r) => {
  const T = r.thresholds;
  const L = [];
  L.push("# Chart palette validation", "");
  L.push(
    "Generated by `build.mjs`. Do not edit by hand. Re-run `node tools/chart-palette/build.mjs` after changing `palette.mjs`.",
    "",
  );
  L.push(
    "CVD is simulated with Machado, Oliveira and Fernandes (2009) at severity 1.0. Contrast is WCAG 2.2.",
    "ΔE is CIEDE2000. Surfaces come from `DiamondDSTokens.css`: chart surface is `--ds-surface`, raised surface (hover, tooltip, menu) is `--ds-elevation-8`, dialog surface is `--ds-elevation-16`. Charts must be drawn on `--ds-surface` or `--ds-background` (a Paper, or the page itself, not a card above elevation 0 or a raised surface). The 3:1 gate holds on those two and is not guaranteed on other surfaces. Raised and dialog surfaces are measured because tooltips, hover cards and dialogs show series colours as swatches.",
    "",
  );
  L.push("## Checks", "", "| Result | Check |", "| --- | --- |");
  for (const c of r.checks)
    L.push(`| ${c.gate ? (c.pass ? "pass" : "FAIL") : "note"} | ${c.label} |`);
  L.push("");

  L.push("## Slots and contrast", "");
  L.push(
    "Contrast is WCAG, shown as chart (the lower of surface and background) / raised / dialog. L* is CIE lightness. Min opacity is the lowest fill opacity that still reaches 3:1 on both chart surfaces.",
    "",
  );
  L.push(
    "| Slot | Name | Light | Dark | Light contrast | Dark contrast | L* light / dark | Min opacity light / dark |",
  );
  L.push("| --- | --- | --- | --- | --- | --- | --- | --- |");
  SLOTS.forEach((s, i) => {
    const l = r.modes.light.slots[i];
    const d = r.modes.dark.slots[i];
    const c = (x) =>
      `${round(Math.min(...CHART_SURFACES.map((k) => x.contrast[k])), 2)} / ${round(x.contrast.raised, 2)} / ${round(x.contrast.dialog, 2)}`;
    L.push(
      `| ${i + 1} | ${s.name} | \`${s.light}\` | \`${s.dark}\` | ${c(l)} | ${c(d)} | ${round(l.lstar)} / ${round(d.lstar)} | ${l.minAlpha} / ${d.minAlpha} |`,
    );
  });
  L.push("");

  L.push("## Contrast below 3:1", "");
  L.push(
    `The chart surfaces (\`--ds-surface\` and \`--ds-background\`) hold ${T.contrast}:1 (WCAG 1.4.11) for line and scatter marks. Raised and dialog surfaces hold ${T.contrastFloor}:1, so colours below ${T.contrast}:1 there need direct labels or a data table.`,
    "",
  );
  for (const m of MODES) {
    const u = r.underTarget[m];
    L.push(
      `- ${m}: ${u.length ? u.map((s) => `${s.slot} ${SLOTS[s.slot - 1].name} (${s.surfaces.join(", ")})`).join("; ") : "none"}`,
    );
  }
  L.push("");

  L.push("## Fills and separators", "");
  const fc = (k) =>
    MODES.map((m) => {
      const v = r.modes[m].slots.map((s) => s.fillContrast[k]);
      return `${m} ${Math.min(...v).toFixed(2)}-${Math.max(...v).toFixed(2)}:1`;
    }).join(", ");
  const lcs = MODES.flatMap((m) =>
    r.modes[m].slots.map((s) => s.labelTextContrast),
  );
  const lcAll = MODES.flatMap((m) =>
    r.modes[m].slots.map((s) => s.labelTextContrastAll),
  );
  const lc = (k) => Math[k](...lcs).toFixed(1);
  L.push(
    `- Data fills (bars, points, heatmap cells) use opacity ${OPACITY.data}, and every slot is at least 3:1 opaque. Any lower opacity needs the per-slot minimum above.`,
    `- Area fills (${OPACITY.area}) composite to ${fc("area")} on the surfaces. Decorative: the line carries the information.`,
    `- Range bands (${OPACITY.band}) composite to ${fc("band")}. Decorative only when the band also has a series-coloured edge line; a band that encodes a range on its own does not meet 3:1.`,
    `- Regions drawn on an image use a soft fill (${OPACITY.region}, hover ${OPACITY["region-hover"]}, selected ${OPACITY["region-selected"]}) with a solid series-coloured border, thicker when selected so the state is not carried by colour alone. Add a soft halo in \`--ds-surface\` (about 55% opacity, 1px each side) so the border reads over bright and dark pixels. The fills are decorative, and the border's contrast depends on the image behind it.`,
    `- Labels next to a line use a tint of the series colour (${OPACITY.label}, hover ${OPACITY["label-hover"]}, selected ${OPACITY["label-selected"]}) with a series-coloured border, thicker when selected, and \`--ds-on-surface\` text. On \`--ds-surface\` and \`--ds-background\` the text reaches ${lc("min")}-${lc("max")}:1 across slots, modes and states (${T.textContrast}:1 gated). Keep labels on those surfaces: on raised and dialog surfaces the minimum is ${Math.min(...lcAll).toFixed(1)}:1.`,
    "- Adjacent filled segments (stacked bars and areas, pies) can fall below 3:1 against each other: separate them with a 1-2px `--ds-surface` gap.",
    "- Overlapping translucent fills blend into colours outside the palette. Prefer lines, or keep overlaps to two series.",
    "",
  );

  L.push("## Greyscale and print", "");
  L.push(
    "Pairs closer than 5 L* are indistinguishable in greyscale, print and achromatopsia.",
    "",
    `| Mode | Pairs under 5 L* | Of those, within slots 1-${T.coreSlots} |`,
    "| --- | --- | --- |",
  );
  for (const m of MODES) {
    const close = r.modes[m].greyClose;
    const core = close.filter((g) => g.b <= T.coreSlots);
    L.push(
      `| ${m} | ${close.length} of ${(SLOTS.length * (SLOTS.length - 1)) / 2} | ${core.length ? core.map((g) => `${g.a}↔${g.b}`).join(", ") : "none"} |`,
    );
  }
  L.push(
    "",
    `Lightness alone does not separate this palette. Where greyscale or print matters, markers are mandatory, not optional.`,
    "",
  );

  L.push("## Text use", "");
  L.push(
    `Series colours are for marks. Set labels, values and legend text in neutral text tokens and show the series colour as a swatch. Only these slots reach WCAG ${T.textContrast}:1 and APCA |Lc| ${T.textLc} on every supported surface, if you must colour text: light ${r.modes.light.textSlots.join(", ") || "none"}; dark ${r.modes.dark.textSlots.join(", ") || "none"}.`,
    "",
  );

  L.push("## Rendering the second channel", "");
  L.push(
    `- Lines at least ${LINE.width}px wide, markers at least ${LINE.marker}px across, with a 1.5px \`--ds-surface\` halo on filled markers.`,
    `- All slots are solid lines, so on a line chart they differ by colour and marker only. The core (slots 1-${T.coreSlots}) holds a CVD floor of ΔE ${T.cvd}, so colour carries it; the additional slots may fall below it (see Weak pairs).`,
    "- Markers only help if the chart library actually draws them. Check this per adapter.",
    "- Forced-colors (Windows high contrast) can replace series colours with system colours. Keep `forced-color-adjust: none` on series marks, or rely on markers, which still render.",
    "- WCAG 1.4.1: never use colour alone. Always pair with a legend and direct labels or a data table.",
    "",
  );

  L.push("## Worst-case pair ΔE", "");
  L.push(
    `Bold is below target (normal ${T.normal}, CVD ${T.cvd}). The CVD target applies to slots 1-${T.coreSlots} only.`,
    "",
  );
  L.push(
    "| Mode | Pairs | Normal | Protan | Deutan | Tritan |",
    "| --- | --- | --- | --- | --- | --- |",
  );
  for (const m of MODES) {
    for (const [label, w, cvdMin] of [
      [`1-${T.coreSlots}`, r.modes[m].worstCore, T.cvd],
      ...(SLOTS.length > T.coreSlots
        ? [[`1-${SLOTS.length}`, r.modes[m].worstAll, 0]]
        : []),
    ]) {
      const c = (v, min) => `${cell(w[v].value, min)} (${w[v].pair.join("↔")})`;
      L.push(
        `| ${m} | ${label} | ${c("normal", T.normal)} | ${c("protan", cvdMin)} | ${c("deutan", cvdMin)} | ${c("tritan", cvdMin)} |`,
      );
    }
  }
  L.push("");

  L.push("## Order: worst pair among the first N slots", "");
  L.push(
    "Each row is the worst pair among slots 1 to N. Later slots are never closer to the earlier ones than the row shows.",
    "",
  );
  L.push(
    "| First N | Light normal | Light CVD | Dark normal | Dark CVD |",
    "| --- | --- | --- | --- | --- |",
  );
  r.modes.light.prefix.forEach((p, k) => {
    const d = r.modes.dark.prefix[k];
    const cvd = (q) => f1(Math.min(...CVD_TYPES.map((v) => q[v])));
    L.push(
      `| ${p.slots} | ${f1(p.normal)} | ${cvd(p)} | ${f1(d.normal)} | ${cvd(d)} |`,
    );
  });
  L.push("");

  L.push("## Weak pairs and their second channel", "");
  if (!r.weakPairs.length) {
    L.push(
      `None. Every pair clears ΔE ${T.cvdWeak} under protan, deutan and tritan in both modes (worst ${f1(Math.min(...MODES.flatMap((m) => CVD_TYPES.map((v) => r.modes[m].worstAll[v].value))))}), so colour carries every slot. Every slot still has its own marker shape for greyscale, print and forced-colors.`,
      "",
    );
  } else {
    L.push(
      `Pairs below ΔE ${T.cvdWeak} under some CVD type in either mode. Every slot is a solid line with its own marker shape, so these pairs rely on the marker. See Rendering the second channel for the sizes this needs.`,
      "",
    );
  }
  for (const w of r.weakPairs) {
    const a = `${w.a} ${SLOTS[w.a - 1].name}`;
    const b = `${w.b} ${SLOTS[w.b - 1].name}`;
    const ok = (x) => (x.value >= T.cvdWeak ? " (ok)" : "");
    L.push(
      `- ${a} / ${b}: ${w.light.type} ${f1(w.light.value)}${ok(w.light)} light, ${w.dark.type} ${f1(w.dark.value)}${ok(w.dark)} dark. Told apart by marker shape.`,
    );
  }
  L.push("");

  L.push("## Light and dark identity", "");
  L.push(
    "Each slot keeps its hue family across modes, with lightness tuned per mode. Names follow the dark hue. Hue gap is the OKLCH hue difference between the two values.",
    "",
    "| Slot | Name | Light | Dark | Hue gap | L* light / dark |",
    "| --- | --- | --- | --- | --- | --- |",
  );
  SLOTS.forEach((s, i) => {
    const l = r.modes.light.slots[i];
    const d = r.modes.dark.slots[i];
    L.push(
      `| ${i + 1} | ${s.name} | \`${s.light}\` | \`${s.dark}\` | ${r.hueGaps[i].toFixed(0)}° | ${round(l.lstar)} / ${round(d.lstar)} |`,
    );
  });
  L.push(
    "",
    `A slot's dark value is nearer to its own light value than to any other slot's, except for slots ${r.identityFails.join(", ") || "none"}. Recorded, not gated.`,
    "",
  );

  L.push("## Distance from status and primary/brand colours", "");
  L.push(
    "Recorded, not gated: a series resembling a status colour is accepted in charts. Nearest token by ΔE across danger, success, warning, info, primary and brand (main, emphasis, accent, solid roles). Hue gap is the smallest OKLCH hue difference to any of them.",
    "",
  );
  L.push(
    "| Slot | Name | Light nearest | Light ΔE | Light hue gap | Dark nearest | Dark ΔE | Dark hue gap |",
    "| --- | --- | --- | --- | --- | --- | --- | --- |",
  );
  SLOTS.forEach((s, i) => {
    const l = r.modes.light.slots[i];
    const d = r.modes.dark.slots[i];
    L.push(
      `| ${i + 1} | ${s.name} | \`${l.nearestReserved.token}\` | ${f1(l.nearestReserved.deltaE)} | ${l.minHueGap.toFixed(0)}° | \`${d.nearestReserved.token}\` | ${f1(d.nearestReserved.deltaE)} | ${d.minHueGap.toFixed(0)}° |`,
    );
  });
  L.push("");
  return L.join("\n");
};
